// Bare tokens that are ordinary English words or well-known other referents, and so are
// NOT sufficient on their own to attribute an article. Every company still matches via
// its qualified forms, so real coverage is unaffected. Word boundaries do not help here —
// the token matches exactly.
//
// If you change the roster, RE-DERIVE this list. The method is "profile the corpus, see
// which names collide", not this specific set of strings.
export const ambiguousBareTokens = [
  'copilot',   // Microsoft brands a dozen unrelated products Copilot
  'cody',      // a given name, and a town in Wyoming
  'devin',     // a given name
  'aider',     // 'aid'/'aider' in ordinary and French text
  'bolt',      // Usain Bolt · a fastener · the ride-hailing app · the Disney film
  'lovable',   // plain English adjective
  'codex',     // Codex Alimentarius · medieval manuscripts · Warhammer codices
  'claude',    // Claude Monet · Claude Debussy · anyone named Claude
  'cursor',    // mouse cursor · database cursor · CSS `cursor:`
  'windsurf',  // the watersport
  'v0',        // version strings: "v0.1.2", "v0 release" — almost never the Vercel product
  // Deliberately absent: 'replit' — distinctive standalone.
];

/**
 * Names that must NEVER reappear in this codebase.
 *
 * When a deployment is retargeted from one market to another, the old market's brand
 * names have a habit of surviving in prompts, few-shot examples, User-Agent strings and
 * test fixtures long after the roster changed — where they quietly corrupt classification
 * and leak the previous engagement. `npm run smoke` fails if any name listed here appears
 * anywhere outside `config/`.
 *
 * Empty in the shipped demo, on purpose: this repo has nothing to forget. Add your own
 * previous market's names in `config/companies.local.mjs`, which is gitignored.
 */
export const retiredBrands = [];

export default { companies, ambiguousBareTokens, retiredBrands };
